#define IMAGE_WIDTH 100
#define IMAGE_HEIGHT 120
#define IMAGE_DRAW_RGB565 0
struct image_info {
    u8 *img;
    int len;
    int width;
    int height;
};
/* ------------------------------------------------------------------------------------*/
/**
 * @brief draw_custom_cb 私有回调
 *
 * @param draw_id	绘图id，自行定义
 * @param dst_buf	屏幕显存buf(分块)
 * @param dst_r		显存区域
 * @param src_r		任务绘制区域draw
 * @param bytes_per_pixel	2：565；3：888
 * @param priv		回调句柄，自行定义
 * @param matrix	任务矩阵
 */
/* ------------------------------------------------------------------------------------*/
static void draw_custom_cb(int draw_id, u8 *dst_buf, struct rect *dst_r, struct rect *src_r, u8 bytes_per_pixel, void *priv, void *matrix)
{
    //draw_id //私有id
    if (draw_id != IMAGE_DRAW_RGB565) {
        return;
    }
    //私有句柄
    struct image_info *pinfo = (struct image_info *)priv;
    u8 *image_src = (u8 *)pinfo->img;
    printf("%s 0x%x", __func__, (u32)image_src);
    //
    int dst_stride = (dst_r->width * bytes_per_pixel + 3) / 4 * 4;
    int src_stride = (src_r->width * bytes_per_pixel + 3) / 4 * 4;
    struct rect r;
    if (get_rect_cover(dst_r, src_r, &r)) {
        for (int h = 0; h < r.height; h++) {
            memcpy(&dst_buf[(r.top + h - dst_r->top) * dst_stride + (r.left - dst_r->left) * bytes_per_pixel],
                   &image_src[(r.top + h - src_r->top)*src_stride + (r.left - src_r->left) * bytes_per_pixel],
                   r.width * bytes_per_pixel);
        }
    }
}
static void gpu_demo_custom_draw(pJLGPUTaskHead_t head, void *priv, int priv_len)
{
    jlgpu_task_basic_param_init(GPU_TASK_DRAW, 0x1, 0);
    task_param.format = GPU_FORMAT_RGB565;
    task_param.draw.left = 20;
    task_param.draw.top = 100;
    task_param.draw.width = IMAGE_WIDTH;
    task_param.draw.height = IMAGE_HEIGHT;
    jlgpu_get_win_rect(&task_param.area);
    task_param.cb_func =  draw_custom_cb;

    pJLGPUTaskUnit_t taskp = jlgpu_get_task_by_id(head, task_param.task_id, task_param.element_id);
    if (taskp) {
        if (taskp->info.draw_info) {//如果指针长度不一致需要free重新申请
            task_param.priv = taskp->info.draw_info->priv;
        }
    }
    if (!task_param.priv) {
        task_param.priv = zalloc(priv_len);//在任务销毁时释放
    }

    memcpy(task_param.priv, priv, priv_len);
    task_param.priv_len = priv_len;
    task_param.draw_id = IMAGE_DRAW_ID;//自定义回调id
    task_param.draw_en = 1;

    jlgpu_update_task_by_id(head, task_param.task_id, task_param.element_id, &task_param);
}

void gpu_demo_custom_draw_demo(pJLGPUTaskHead_t head)
{
    struct image_info info = {
        .img = 	test_image_rgb16,
        .len = ARRAY_SIZE(test_image_rgb16),
        .width = IMAGE_WIDTH,
        .height = IMAGE_HEIGHT,
    } ;
    gpu_demo_custom_draw(head, (void *)&info, sizeof(struct image_info));
}
